<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';
use App\Core\Csrf;use App\Core\Database;use App\Services\DivisionProgressionService;use App\Services\CompetitorIdentityService;use App\Services\SpecialCategoryService;use App\Services\JackJillCompetitorEligibilityService;
$pdo=Database::connection();$token=trim((string)($_GET['token']??$_POST['token']??''));if($token===''){http_response_code(403);exit('Registration Desk link is missing.');}
$stmt=$pdo->prepare("SELECT l.*,e.name event_name,e.event_date FROM bdc_registration_desk_links l JOIN bdc_events e ON e.id=l.event_id WHERE l.token_hash=:hash AND l.is_enabled=1 AND (l.expires_at IS NULL OR l.expires_at>NOW()) LIMIT 1");$stmt->execute(['hash'=>hash('sha256',$token)]);$desk=$stmt->fetch();if(!$desk){http_response_code(403);exit('This Registration Desk link is invalid, disabled or expired.');}$deskDance=in_array((string)($desk['dance_style']??'bachata'),['bachata','salsa'],true)?(string)$desk['dance_style']:'bachata';
$requestedRoundId=(int)($_GET['round_id']??$_POST['round_id']??0);$roundSql=$requestedRoundId>0?"SELECT * FROM bdc_scoring_rounds WHERE id=:round AND event_id=:event AND dance_style=:dance AND division=:division AND status<>'archived' LIMIT 1":"SELECT * FROM bdc_scoring_rounds WHERE event_id=:event AND dance_style=:dance AND division=:division AND status NOT IN('archived','completed') ORDER BY id DESC LIMIT 1";$roundStmt=$pdo->prepare($roundSql);$params=['event'=>$desk['event_id'],'dance'=>$deskDance,'division'=>$desk['division']];if($requestedRoundId>0)$params['round']=$requestedRoundId;$roundStmt->execute($params);$round=$roundStmt->fetch();if(!$round){http_response_code(404);exit('The selected scoring round is not available for this Registration Desk link.');}$roundId=(int)$round['id'];
function logDesk(PDO $pdo,array $desk,string $action,array $entry,array $details=[]):void{$s=$pdo->prepare("INSERT INTO bdc_registration_desk_activity(desk_link_id,event_id,division,action,competitor_id,competitor_name,details) VALUES(:link,:event,:division,:action,:competitor,:name,:details)");$s->execute(['link'=>$desk['id'],'event'=>$desk['event_id'],'division'=>$desk['division'],'action'=>$action,'competitor'=>$entry['competitor_id']??$entry['id']??null,'name'=>$entry['display_name']??$entry['exact_name']??null,'details'=>json_encode($details,JSON_UNESCAPED_SLASHES)]);}
function deskEntries(PDO $pdo,int $roundId,string $dance='bachata'):array{$s=$pdo->prepare("SELECT se.id,se.competitor_id,se.dance_role,se.bib_number,se.display_name,se.entry_status,se.desk_checked_in,se.desk_ready,se.desk_updated_at,se.updated_at,CASE WHEN :dance='salsa' THEN sdc.sdc_id ELSE c.bdc_id END bdc_id FROM bdc_scoring_entries se LEFT JOIN bdc_competitors c ON c.id=se.competitor_id LEFT JOIN bdc_sdc_competitors sdc ON sdc.competitor_id=se.competitor_id AND sdc.status='active' WHERE se.round_id=:round ORDER BY se.dance_role,se.bib_number IS NULL,se.bib_number,se.display_name");$s->execute(['dance'=>$dance,'round'=>$roundId]);return $s->fetchAll();}
function respond(array $p,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($p,JSON_UNESCAPED_SLASHES);exit;}
function disciplineProfile(PDO $pdo,int $competitorId,string $dance):?array{$s=$pdo->prepare('SELECT * FROM bdc_competitor_discipline_profiles WHERE competitor_id=:c AND dance_style=:dance LIMIT 1');$s->execute(['c'=>$competitorId,'dance'=>$dance]);return $s->fetch()?:null;}
function ensureDisciplineProfile(PDO $pdo,array $c,string $dance,string $role,string $division):array{$p=disciplineProfile($pdo,(int)$c['id'],$dance);if($p)return $p;$pdo->prepare('INSERT INTO bdc_competitor_discipline_profiles(competitor_id,dance_style,dance_role,current_division) VALUES(:c,:dance,:role,:division)')->execute(['c'=>$c['id'],'dance'=>$dance,'role'=>$role,'division'=>$division]);return ['competitor_id'=>$c['id'],'dance_style'=>$dance,'dance_role'=>$role,'current_division'=>$division];}
function eligibility(PDO $pdo,array $c,string $role,string $division,string $dance):array{if($dance==='bachata'&&SpecialCategoryService::isSpecial($division))return SpecialCategoryService::entryEligibility($division);$profile=disciplineProfile($pdo,(int)$c['id'],$dance);if($profile&&!in_array((string)$profile['dance_role'],[$role,'both','unknown'],true))return ['eligible'=>false,'reason'=>'Registered as '.ucfirst((string)$profile['dance_role']).' for '.ucfirst($dance).'.'];$p=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN division='novice' THEN points ELSE 0 END),0) novice_points,COALESCE(SUM(CASE WHEN division='intermediate' THEN points ELSE 0 END),0) intermediate_points,COALESCE(SUM(CASE WHEN division='advanced' THEN points ELSE 0 END),0) advanced_points FROM bdc_point_transactions WHERE competitor_id=:c AND dance_style=:dance AND dance_role IN(:r,'both')");$p->execute(['c'=>$c['id'],'dance'=>$dance,'r'=>$role]);$points=$p->fetch()?:[];$h=$pdo->prepare("SELECT MAX(division='intermediate') competed_intermediate,MAX(division='advanced') competed_advanced,MAX(division='all_star') competed_all_star FROM (SELECT division FROM bdc_participant_results WHERE competitor_id=:c1 AND dance_style=:dance1 AND dance_role IN(:r1,'both') UNION ALL SELECT division FROM bdc_point_transactions WHERE competitor_id=:c2 AND dance_style=:dance2 AND dance_role IN(:r2,'both')) x");$h->execute(['c1'=>$c['id'],'dance1'=>$dance,'r1'=>$role,'c2'=>$c['id'],'dance2'=>$dance,'r2'=>$role]);$history=$h->fetch()?:[];$current=(string)($profile['current_division']??($dance==='bachata'?($c['current_division']??'unknown'):'unknown'));return DivisionProgressionService::eligibilityFor($division,(float)($points['novice_points']??0),(float)($points['intermediate_points']??0),(float)($points['advanced_points']??0),$current,!empty($history['competed_intermediate']),!empty($history['competed_advanced']),!empty($history['competed_all_star']));}
function findCompetitor(PDO $pdo,string $term):?array{$bdc='';if(preg_match('/^(BDC-\d+)/i',$term,$m))$bdc=strtoupper($m[1]);$s=$pdo->prepare("SELECT id,bdc_id,exact_name,dance_role,current_division,status FROM bdc_competitors WHERE status<>'archived' AND (bdc_id=:bdc OR LOWER(exact_name)=LOWER(:exact)) ORDER BY id LIMIT 1");$s->execute(['bdc'=>$bdc!==''?$bdc:$term,'exact'=>$term]);return $s->fetch()?:null;}
$isAjax=str_contains((string)($_SERVER['HTTP_ACCEPT']??''),'application/json')||($_SERVER['HTTP_X_REQUESTED_WITH']??'')==='XMLHttpRequest';
if(isset($_GET['competitor_search'])){$term=trim((string)$_GET['competitor_search']);$role=(string)($_GET['role']??'');if(!in_array($role,['leader','follower'],true)||mb_strlen($term)<2)respond(['ok'=>true,'competitors'=>[]]);$matches=[];foreach(JackJillCompetitorEligibilityService::directory($pdo,$deskDance,$role,1500) as $c){if(strcasecmp((string)$c['identity_code'],$term)!==0&&!str_contains(mb_strtolower((string)$c['exact_name'],'UTF-8'),mb_strtolower($term,'UTF-8')))continue;$e=DivisionProgressionService::eligibilityFromApprovedHistory($pdo,(int)$c['id'],$role,$deskDance,(string)$round['division']);$matches[]=['bdc_id'=>$c['identity_code'],'name'=>$c['exact_name'],'eligible'=>$e['eligible'],'reason'=>$e['reason'],'profile_role'=>$c['dance_role']];if(count($matches)>=20)break;}respond(['ok'=>true,'competitors'=>$matches]);}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token. Refresh and try again.');$action=(string)($_POST['action']??'');$entryId=(int)($_POST['entry_id']??0);if($action==='add_entry'){$role=(string)($_POST['dance_role']??'');$term=trim((string)($_POST['competitor_search']??''));$rawBib=trim((string)($_POST['bib']??''));$bib=$rawBib===''?null:(int)$rawBib;$create=($_POST['entry_mode']??'existing')==='create';if(!in_array($role,['leader','follower'],true)||$term===''||($bib!==null&&$bib<1))throw new RuntimeException('Choose role and competitor. Bib may be blank.');if($bib!==null){$d=$pdo->prepare("SELECT display_name FROM bdc_scoring_entries WHERE round_id=:round AND dance_role=:role AND bib_number=:bib AND entry_status='active' LIMIT 1");$d->execute(['round'=>$roundId,'role'=>$role,'bib'=>$bib]);if($n=$d->fetchColumn())throw new RuntimeException('Bib '.$bib.' is already assigned to '.$n.'.');}$c=findCompetitor($pdo,$term);if($c){if($create)throw new RuntimeException('This dancer already has '.$c['bdc_id'].'. Use Add Existing.');$e=eligibility($pdo,$c,$role,(string)$round['division'],$deskDance);if(!$e['eligible'])throw new RuntimeException('Cannot add '.$c['exact_name'].': '.$e['reason']);ensureDisciplineProfile($pdo,$c,$deskDance,$role,(string)$round['division']);}else{if(!$create)throw new RuntimeException('No matching BDC competitor. Click Create Name & Add for a genuinely new dancer.');$initial=($deskDance==='bachata'&&SpecialCategoryService::isSpecial((string)$round['division']))?'novice':(string)$round['division'];$c=CompetitorIdentityService::findOrCreateOfficial($pdo,$term,$role,$initial);ensureDisciplineProfile($pdo,$c,$deskDance,$role,$initial);}$pdo->prepare("INSERT INTO bdc_scoring_entries(round_id,competitor_id,dance_role,bib_number,display_name,desk_checked_in,desk_updated_at) VALUES(:round,:c,:role,:bib,:name,0,NOW()) ON DUPLICATE KEY UPDATE bib_number=VALUES(bib_number),display_name=VALUES(display_name),entry_status='active',desk_updated_at=NOW()")->execute(['round'=>$roundId,'c'=>$c['id'],'role'=>$role,'bib'=>$bib,'name'=>$c['exact_name']]);logDesk($pdo,$desk,'competitor_added',$c,['dance_style'=>$deskDance,'role'=>$role,'bib'=>$bib,'new'=>$create]);}else{$s=$pdo->prepare("SELECT * FROM bdc_scoring_entries WHERE id=:id AND round_id=:round");$s->execute(['id'=>$entryId,'round'=>$roundId]);$entry=$s->fetch();if(!$entry)throw new RuntimeException('Entry not found.');if($action==='update_entry'){$raw=trim((string)($_POST['bib']??''));$bib=$raw===''?null:(int)$raw;if($bib!==null&&$bib<1)throw new RuntimeException('Bib must be blank or at least 1.');if($bib!==null){$d=$pdo->prepare("SELECT display_name FROM bdc_scoring_entries WHERE round_id=:round AND dance_role=:role AND bib_number=:bib AND id<>:id AND entry_status='active' LIMIT 1");$d->execute(['round'=>$roundId,'role'=>$entry['dance_role'],'bib'=>$bib,'id'=>$entryId]);if($n=$d->fetchColumn())throw new RuntimeException('Bib '.$bib.' is already assigned to '.$n.'.');}$checked=($_POST['checked']??'0')==='1'?1:0;$ready=($_POST['ready']??'0')==='1'?1:0;$status=(string)($_POST['status']??'active');if(!in_array($status,['active','withdrawn'],true))throw new RuntimeException('Invalid status.');if($status==='withdrawn')$ready=0;$pdo->prepare("UPDATE bdc_scoring_entries SET bib_number=:bib,entry_status=:status,desk_checked_in=:checked,desk_ready=:ready,desk_updated_at=NOW() WHERE id=:id AND round_id=:round")->execute(['bib'=>$bib,'status'=>$status,'checked'=>$checked,'ready'=>$ready,'id'=>$entryId,'round'=>$roundId]);logDesk($pdo,$desk,'entry_updated',$entry,['dance_style'=>$deskDance,'bib'=>$bib,'checked'=>$checked,'ready'=>$ready,'status'=>$status]);}elseif($action==='remove_entry'){$pdo->prepare("UPDATE bdc_scoring_entries SET entry_status='withdrawn',desk_ready=0,desk_updated_at=NOW() WHERE id=:id AND round_id=:round")->execute(['id'=>$entryId,'round'=>$roundId]);logDesk($pdo,$desk,'entry_removed',$entry,['dance_style'=>$deskDance]);}else throw new RuntimeException('Invalid action.');}if($isAjax)respond(['ok'=>true,'entries'=>deskEntries($pdo,$roundId)]);}catch(Throwable $e){if($isAjax)respond(['ok'=>false,'error'=>$e->getMessage()],422);$error=$e->getMessage();}}
if(isset($_GET['live'])){$entries=deskEntries($pdo,$roundId,$deskDance);respond(['ok'=>true,'changed'=>true,'latest'=>date('Y-m-d H:i:s'),'entries'=>$entries]);}
$entries=deskEntries($pdo,$roundId,$deskDance);$csrf=Csrf::token();$label=SpecialCategoryService::isSpecial((string)$desk['division'])?SpecialCategoryService::label((string)$desk['division']):ucfirst((string)$desk['division']);$danceLabel=ucfirst($deskDance);$deskCouncil=JackJillCompetitorEligibilityService::council($deskDance);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BDC Registration Desk</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f3f4f6}.desk-head{background:#111827;color:#fff}.card{border-radius:12px}.leader-head{background:#cfe2ff}.follower-head{background:#f8d7da}.entry-ready{background:#d1e7dd}.missing-bib{background:#fff3cd}.matchbox{z-index:30;max-height:260px;overflow:auto}.bib-input{width:95px}</style></head><body><header class="desk-head py-3"><div class="container-fluid px-4"><h1 class="h4 mb-1">BDC Registration Desk</h1><div><?=e($desk['event_name'])?> · <strong><?=e($danceLabel)?></strong> · <?=e($label)?> · <?=e(ucfirst($round['round_type']))?></div></div></header><main class="container-fluid px-4 py-3"><div id="notice"></div><div class="card shadow-sm border-0 mb-3"><div class="card-body d-flex gap-2 flex-wrap align-items-center"><input id="deskSearch" class="form-control" style="max-width:380px" placeholder="Search registered name, BDC ID or bib"><span class="badge text-bg-success">Live</span><span id="summary" class="text-muted"></span><span id="missingSummary" class="badge text-bg-warning ms-auto"></span></div></div><div class="card shadow-sm mb-3"><div class="card-body"><h2 class="h5 mb-1">Add competitor</h2><div class="text-muted small mb-3">Search the shared BDC ID database. Eligibility and points are checked only against <?=e($danceLabel)?>.</div><div class="row g-2 align-items-end"><div class="col-md-2"><label class="form-label">Role</label><select id="addRole" class="form-select"><option value="leader">Leader</option><option value="follower">Follower</option></select></div><div class="col-md-5 position-relative"><label class="form-label">Competitor</label><input id="competitorSearch" class="form-control" placeholder="Type competitor name or BDC ID" autocomplete="off"><div id="matches" class="list-group position-absolute w-100 shadow matchbox"></div></div><div class="col-md-2"><label class="form-label">Bib</label><input id="addBib" type="number" min="1" class="form-control" placeholder="Optional"></div><div class="col-md-3 d-flex gap-2"><button id="addExisting" class="btn btn-primary flex-fill">Add Existing</button><button id="createAdd" class="btn btn-outline-primary flex-fill">Create Name & Add</button></div></div></div></div><div class="row g-3" id="rolePanels"></div></main><script>
const token=<?=json_encode($token)?>,roundId=<?=$roundId?>,csrf=<?=json_encode($csrf)?>;let entries=<?=json_encode($entries,JSON_UNESCAPED_SLASHES)?>,selected='';const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function render(){const q=document.querySelector('#deskSearch').value.toLowerCase();let missingAll=0;document.querySelector('#rolePanels').innerHTML=['leader','follower'].map(role=>{const rows=entries.filter(e=>e.dance_role===role&&e.entry_status==='active'&&(!q||(`${e.display_name} ${e.bdc_id||''} ${e.bib_number||''}`).toLowerCase().includes(q)));const missing=rows.filter(e=>!e.bib_number).length;missingAll+=missing;return `<div class="col-xl-6"><div class="card shadow-sm h-100"><div class="card-header ${role==='leader'?'leader-head':'follower-head'}"><strong>${role==='leader'?'Leaders':'Followers'}</strong><span class="float-end badge text-bg-primary">${rows.length} total · ${rows.filter(e=>+e.desk_ready).length} ready · ${missing} missing bib</span></div><div class="card-body"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Bib</th><th>Competitor</th><th>BDC ID</th><th>Checked In</th><th>Ready</th><th>Status</th></tr></thead><tbody>${rows.map(e=>`<tr class="${+e.desk_ready?'entry-ready':(!e.bib_number?'missing-bib':'')}"><td><input class="form-control form-control-sm bib-input" type="number" min="1" value="${e.bib_number||''}" onchange="updateEntry(${e.id},this.value,${+e.desk_checked_in},${+e.desk_ready},'active')"></td><td>${esc(e.display_name)}</td><td><code>${esc(e.bdc_id||'')}</code></td><td><input type="checkbox" ${+e.desk_checked_in?'checked':''} onchange="updateEntry(${e.id},${e.bib_number||0},this.checked?1:0,${+e.desk_ready},'active')"></td><td><input type="checkbox" ${+e.desk_ready?'checked':''} onchange="updateEntry(${e.id},${e.bib_number||0},${+e.desk_checked_in},this.checked?1:0,'active')"></td><td><button class="btn btn-sm btn-outline-danger" onclick="removeEntry(${e.id})">Remove</button></td></tr>`).join('')||'<tr><td colspan="6" class="text-muted text-center py-4">No competitors</td></tr>'}</tbody></table></div></div></div></div>`}).join('');document.querySelector('#summary').textContent=entries.filter(e=>e.entry_status==='active').length+' active competitors';document.querySelector('#missingSummary').textContent=missingAll+' missing bib';}
async function api(params){params.set('_csrf',csrf);params.set('token',token);params.set('round_id',roundId);const r=await fetch(location.pathname,{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json','Content-Type':'application/x-www-form-urlencoded'},body:params.toString()});const d=await r.json();if(!d.ok)throw new Error(d.error||'Request failed');if(d.entries)entries=d.entries;render();}
async function updateEntry(id,bib,checked,ready,status){try{const p=new URLSearchParams({action:'update_entry',entry_id:id,bib:bib||'',checked,ready,status});await api(p);}catch(e){alert(e.message);}}
async function removeEntry(id){if(!confirm('Remove this competitor from the active round?'))return;try{await api(new URLSearchParams({action:'remove_entry',entry_id:id}));}catch(e){alert(e.message);}}
async function add(mode){const term=selected||document.querySelector('#competitorSearch').value.trim();if(!term)return;try{await api(new URLSearchParams({action:'add_entry',dance_role:document.querySelector('#addRole').value,competitor_search:term,bib:document.querySelector('#addBib').value,entry_mode:mode}));document.querySelector('#competitorSearch').value='';document.querySelector('#addBib').value='';selected='';document.querySelector('#matches').innerHTML='';}catch(e){alert(e.message);}}
document.querySelector('#addExisting').onclick=()=>add('existing');document.querySelector('#createAdd').onclick=()=>{if(confirm('Create a new BDC ID only if this dancer genuinely has no existing BDC record?'))add('create');};document.querySelector('#deskSearch').oninput=render;let searchTimer;document.querySelector('#competitorSearch').oninput=e=>{selected='';clearTimeout(searchTimer);const term=e.target.value.trim();if(term.length<2){document.querySelector('#matches').innerHTML='';return;}searchTimer=setTimeout(async()=>{const u=new URL(location.href);u.searchParams.set('competitor_search',term);u.searchParams.set('role',document.querySelector('#addRole').value);const r=await fetch(u,{headers:{'Accept':'application/json','X-Requested-With':'XMLHttpRequest'}});const d=await r.json();document.querySelector('#matches').innerHTML=(d.competitors||[]).map(c=>`<button type="button" class="list-group-item list-group-item-action ${c.eligible?'':'list-group-item-warning'}" data-bdc="${esc(c.bdc_id)}"><strong>${esc(c.name)}</strong> · ${esc(c.bdc_id)}<div class="small">${c.eligible?'Eligible':esc(c.reason||'Not eligible')}</div></button>`).join('');document.querySelectorAll('#matches [data-bdc]').forEach(b=>b.onclick=()=>{selected=b.dataset.bdc;document.querySelector('#competitorSearch').value=b.dataset.bdc;document.querySelector('#matches').innerHTML='';});},250);};render();setInterval(async()=>{if(document.hidden)return;try{const u=new URL(location.href);u.searchParams.set('live','1');const r=await fetch(u,{headers:{'Accept':'application/json'}});const d=await r.json();if(d.ok&&d.entries){entries=d.entries;render();}}catch(e){}},10000);
</script></body></html>
